+		var taskLocks []Lock
+		if err := request("GET", "/api/tasks/"+url.PathEscape(task.ID)+"/locks?active=true", nil, &taskLocks); err != nil {
+			warnings = append(warnings, "Could not read locks for "+task.ID+": "+err.Error())
