		if branch == "" {
			branch = "main"
		}
		var out Repository
		body := map[string]any{"project_id": projectID, "name": name, "path": mcpArg(args, "path"), "default_branch": branch}
		if err := request("POST", "/api/repositories", body, &out); err != nil {
			return nil, err
		}
		return mcpToolResult(out), nil
